SELECT id, practice_script->>'version' AS version, md5(practice_script::text) AS huella FROM public.nodes WHERE id IN ('3.1','3.2','3.3','3.4','3.6','3.8','3.9','3.9b','3.10','7.1','7.3','5.15','7.0','7.4') ORDER BY id;
SELECT id, md5(concat_ws('|', paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default)) AS huella FROM public.reglas WHERE id IN ('discovery.barrido','discovery.bordes_restriccion','discovery.confirmacion_con_sus_palabras','discovery.dolor_directo','discovery.escalera_capas','discovery.fabrica_dolor','discovery.hueco','discovery.hueco_inventado','discovery.interrogatorio','discovery.lectura_falsa','discovery.lee_el_lugar','discovery.opinion_de_precio','discovery.pregunta_especifica','discovery.presiona_compromiso','discovery.qtqp','discovery.receta_sin_diagnostico','discovery.rojo_insistir','discovery.rojo_vs_amarrado','discovery.solo_cerradas','discovery.suelta_amarrado','discovery.suggestive_language','discovery.escucha') ORDER BY id;
SELECT max(version) AS version_cerebro, count(*) AS secciones, md5(string_agg(body, '#' ORDER BY order_index)) AS huella_cerebro FROM public.doctrina WHERE is_active;
SELECT node_id, card_order, md5(body) AS huella FROM public.node_cards WHERE (node_id, card_order) IN (('3.0',6),('3.10',1),('3.2',9)) ORDER BY node_id, card_order;
SELECT id, regla_id, md5(short_description) AS huella FROM public.skills WHERE id IN ('discovery.escucha_activa','discovery.dolor_real','qualification.luz_verde') ORDER BY id;
